diff --git a/drivers/md/md.c b/drivers/md/md.c
index b4067b9afd38296a023fad0d8f0d140cb35a75fd..2ffd277eb31193a69a10467da12f110bfd65431e 100644
--- a/drivers/md/md.c
+++ b/drivers/md/md.c
@@ -5645,8 +5645,7 @@ static int get_bitmap_file(struct mddev * mddev, void __user * arg)
 	char *ptr, *buf = NULL;
 	int err = -ENOMEM;

-	file = kmalloc(sizeof(*file), GFP_NOIO);
-
+	file = kzalloc(sizeof(*file), GFP_NOIO);
 	if (!file)
 		goto out;

oracle_patch.text:
diff --git a/drivers/md/md.c b/drivers/md/md.c
index ea8a181b3131f07b2e2d5043c6bfbba290b8bc15..d7e92423ba267efa37a452cf04735ef4cc34de64 100644
--- a/drivers/md/md.c
+++ b/drivers/md/md.c
@@ -5384,9 +5384,9 @@ static int get_bitmap_file(struct mddev * mddev, void __user * arg)
 	int err = -ENOMEM;

 	if (md_allow_write(mddev))
-		file = kmalloc(sizeof(*file), GFP_NOIO);
+		file = kzalloc(sizeof(*file), GFP_NOIO);
 	else
-		file = kmalloc(sizeof(*file), GFP_KERNEL);
+		file = kzalloc(sizeof(*file), GFP_KERNEL);

 	if (!file)
 		goto out;
